  "prompt": "A: Tôi làm kế toán đã mười năm, gần đây muốn chuyển sang phân tích dữ liệu, nhưng lo tuổi mình không còn lợi thế.\nB: Thực ra kinh nghiệm kế toán của anh là một lợi thế lớn, vì anh rất nhạy với ý nghĩa đằng sau các con số.\nA: Nhưng tôi gần như không biết lập trình.\nB: Có thể bắt đầu từ những công cụ cơ bản, vừa làm vừa học. Quan trọng là chọn một hướng đi cụ thể rồi kiên trì theo đuổi.\nA: Nghe chị nói vậy, tôi thấy tự tin hơn nhiều.\nB: Chuyển ngành giữa chừng tất nhiên không dễ, nhưng hoàn toàn không phải là không thể.",
  "answer": "A：我做了十年会计，最近想转行做数据分析，但担心自己的年龄已经不占优势了。\nB：其实您的会计经验是一大优势，因为您对数字背后的含义非常敏感。\nA：可是我几乎不会编程。\nB：可以先从基础工具学起，边做边学。关键是选定一个具体方向，然后坚持下去。\nA：听您这么一说，我觉得有信心多了。\nB：中途转行固然不容易，但并不是不可能。",
