  "hsk20_level": null,
  "title": "Thơ Đường",
  "prompt": "唐诗是中国古典文学的瑰宝，其语言凝练、意境深远，千百年来传诵不衰。李白的豪放、杜甫的沉郁，展现出截然不同的艺术风格。对于外国学习者而言，读懂唐诗不仅需要扎实的语言功底，还需要了解其创作背景。然而，一旦领会其中的韵味，便能体会到跨越时空的情感共鸣。",
  "answer": "Thơ Đường là báu vật của văn học cổ điển Trung Quốc, ngôn ngữ cô đọng, ý cảnh sâu xa, hàng nghìn năm nay vẫn được truyền tụng không ngớt. Sự phóng khoáng của Lý Bạch và nỗi trầm uất của Đỗ Phủ cho thấy những phong cách nghệ thuật hoàn toàn khác biệt. Đối với người học nước ngoài, để đọc hiểu thơ Đường không chỉ cần nền tảng ngôn ngữ vững chắc mà còn cần hiểu bối cảnh sáng tác. Tuy nhiên, một khi nắm được cái hay trong đó, người đọc sẽ cảm nhận được sự đồng điệu cảm xúc vượt qua không gian và thời gian.",
  "pinyin": "Tángshī shì Zhōngguó gǔdiǎn wénxué de guībǎo, qí yǔyán níngliàn, yìjìng shēnyuǎn, qiān bǎi nián lái chuánsòng bù shuāi. Lǐ Bái de háofàng, Dù Fǔ de chényù, zhǎnxiàn chū jiérán bù tóng de yìshù fēnggé. Duìyú wàiguó xuéxízhě ér yán, dú dǒng Tángshī bùjǐn xūyào zhāshi de yǔyán gōngdǐ, hái xūyào liǎojiě qí chuàngzuò bèijǐng. Rán'ér, yídàn lǐnghuì qízhōng de yùnwèi, biàn néng tǐhuì dào kuàyuè shíkōng de qínggǎn gòngmíng.",
  "alternative_answers": [],
