  "title": "Lối sống tối giản",
  "prompt": "Mấy năm gần đây, “lối sống tối giản” ngày càng được giới trẻ ưa chuộng. Họ cho rằng đồ đạc trong nhà không cần nhiều, chỉ cần giữ lại những thứ thật sự cần thiết là đủ. Như vậy không chỉ tiết kiệm được kha khá tiền mà dọn dẹp cũng nhẹ nhàng hơn nhiều. Tuy nhiên, tối giản không có nghĩa là không mua gì cả, mà là phải cân nhắc kỹ trước khi mua.",
  "answer": "近几年，“极简生活”越来越受年轻人欢迎。他们认为家里的东西不需要太多，只要留下真正需要的就够了。这样不但能节省不少钱，打扫起来也轻松得多。不过，极简并不意味着什么都不买，而是买之前要认真考虑。",
  "pinyin": "Jìn jǐ nián, “jíjiǎn shēnghuó” yuèláiyuè shòu niánqīngrén huānyíng. Tāmen rènwéi jiā li de dōngxi bù xūyào tài duō, zhǐyào liúxià zhēnzhèng xūyào de jiù gòu le. Zhèyàng búdàn néng jiéshěng bù shǎo qián, dǎsǎo qǐlái yě qīngsōng de duō. Búguò, jíjiǎn bìng bú yìwèizhe shénme dōu bù mǎi, ér shì mǎi zhīqián yào rènzhēn kǎolǜ.",
