  "title": "Thương mại Việt – Trung",
  "prompt": "中国长期以来是越南最大的贸易伙伴，双边贸易额持续增长。越南向中国出口的农产品，如榴莲、火龙果等，深受中国消费者青睐。与此同时，越南从中国进口大量机械设备和原材料，用于制造业生产。不过，物流成本高、检验标准不统一等问题，仍制约着贸易的进一步发展。",
  "answer": "Trung Quốc từ lâu là đối tác thương mại lớn nhất của Việt Nam, kim ngạch thương mại song phương liên tục tăng. Các mặt hàng nông sản Việt Nam xuất khẩu sang Trung Quốc như sầu riêng, thanh long… rất được người tiêu dùng Trung Quốc ưa chuộng. Đồng thời, Việt Nam nhập khẩu từ Trung Quốc một lượng lớn máy móc thiết bị và nguyên vật liệu phục vụ sản xuất chế tạo. Tuy nhiên, những vấn đề như chi phí logistics cao, tiêu chuẩn kiểm định chưa thống nhất vẫn đang kìm hãm sự phát triển hơn nữa của thương mại.",
  "pinyin": "Zhōngguó chángqī yǐlái shì Yuènán zuì dà de màoyì huǒbàn, shuāngbiān màoyì'é chíxù zēngzhǎng. Yuènán xiàng Zhōngguó chūkǒu de nóngchǎnpǐn, rú liúlián, huǒlóngguǒ děng, shēn shòu Zhōngguó xiāofèizhě qīnglài. Yǔ cǐ tóngshí, Yuènán cóng Zhōngguó jìnkǒu dàliàng jīxiè shèbèi hé yuáncáiliào, yòng yú zhìzàoyè shēngchǎn. Búguò, wùliú chéngběn gāo, jiǎnyàn biāozhǔn bù tǒngyī děng wèntí, réng zhìyuē zhe màoyì de jìn yí bù fāzhǎn.",
