  "prompt": "上中学的时候，我和父母常常因为一些小事意见不同。那时候我觉得他们一点也不理解我。后来我离开家去外地上大学，才明白他们的很多担心都是因为爱我。现在我每个周末都会给他们打电话，聊聊最近的生活。",
  "answer": "Hồi học trung học, tôi và bố mẹ thường bất đồng vì những chuyện nhỏ. Khi đó tôi thấy bố mẹ chẳng hiểu tôi chút nào. Về sau tôi xa nhà đi học đại học ở nơi khác, mới hiểu rằng phần lớn nỗi lo của bố mẹ đều là vì thương tôi. Bây giờ cuối tuần nào tôi cũng gọi điện cho bố mẹ, kể chuyện cuộc sống dạo này.",
  "pinyin": "Shàng zhōngxué de shíhou, wǒ hé fùmǔ chángcháng yīnwèi yìxiē xiǎo shì yìjiàn bù tóng. Nà shíhou wǒ juéde tāmen yìdiǎn yě bù lǐjiě wǒ. Hòulái wǒ líkāi jiā qù wàidì shàng dàxué, cái míngbai tāmen de hěn duō dānxīn dōu shì yīnwèi ài wǒ. Xiànzài wǒ měi gè zhōumò dōu huì gěi tāmen dǎ diànhuà, liáoliao zuìjìn de shēnghuó.",
