  "prompt": "家庭是孩子的第一所学校，父母的一言一行都在潜移默化地影响着孩子。与其一味地说教，不如以身作则，用自己的行动去诠释责任与善良。然而，现实中不少父母把自身的焦虑投射到孩子身上，导致亲子关系日趋紧张。教育的本质，或许正是在陪伴中给予孩子成长的空间。",
  "answer": "Gia đình là ngôi trường đầu tiên của trẻ; từng lời nói, việc làm của cha mẹ đều âm thầm ảnh hưởng đến con. Thay vì một mực răn dạy, chi bằng cha mẹ làm gương, dùng chính hành động của mình để thể hiện thế nào là trách nhiệm và lòng tốt. Tuy nhiên, trên thực tế, không ít cha mẹ đem nỗi lo âu của chính mình trút lên con, khiến quan hệ giữa cha mẹ và con cái ngày càng căng thẳng. Bản chất của giáo dục có lẽ chính là vừa đồng hành vừa cho trẻ không gian để lớn lên.",
  "pinyin": "Jiātíng shì háizi de dì-yī suǒ xuéxiào, fùmǔ de yì yán yì xíng dōu zài qiányí-mòhuà de yǐngxiǎng zhe háizi. Yǔqí yíwèi de shuōjiào, bùrú yǐshēn-zuòzé, yòng zìjǐ de xíngdòng qù quánshì zérèn yǔ shànliáng. Rán'ér, xiànshí zhōng bù shǎo fùmǔ bǎ zìshēn de jiāolǜ tóushè dào háizi shēn shang, dǎozhì qīnzǐ guānxì rìqū jǐnzhāng. Jiàoyù de běnzhì, huòxǔ zhèng shì zài péibàn zhōng jǐyǔ háizi chéngzhǎng de kōngjiān.",
