  "answer": "A：最近妈妈的身体越来越差，我想跟你商量一下，要不要送她去养老院。\nB：我不太赞成。妈辛苦了一辈子，现在老了反而把她送出去，别人会怎么看？\nA：我明白你的顾虑。可是我们俩都要上班，白天家里没人，万一妈出了什么事，后果会很严重。\nB：这样吧，我们先请一个专门照顾老人的保姆，看看妈能不能适应，再听听她自己的意见。\nA：好，最重要的是尊重妈妈本人的意愿。",
