  "prompt": "Nhiều người trẻ có thói quen thức khuya, nửa đêm vẫn đang lướt điện thoại. Thiếu ngủ kéo dài sẽ khiến sức đề kháng suy giảm, tinh thần cũng kém đi. Bác sĩ khuyên nên cố gắng đi ngủ trước mười một giờ, và không dùng điện thoại nửa tiếng trước khi ngủ. Một giấc ngủ chất lượng mới là liều thuốc bổ tốt nhất.",
  "answer": "很多年轻人有熬夜的习惯，半夜还在看手机。长期睡眠不足会导致免疫力下降，精神状态也会变差。医生建议，尽量在十一点以前睡觉，睡前半小时不要玩手机。高质量的睡眠才是最好的补品。",
