  "prompt": "现在很多城市开始要求人们把垃圾分开放。比如，纸和塑料瓶可以再用，吃剩的饭菜要放进另一个垃圾桶。刚开始大家觉得很麻烦，但慢慢地就习惯了。把垃圾分开放不但能保护环境，还可以让有用的东西被再次使用。",
