  "hsk20_level": null,
  "title": "Vi nhựa",
  "prompt": "塑料制品在给人类生活带来便利的同时，也留下了难以降解的隐患。研究人员在深海、极地乃至人体血液中都检测到了微塑料的存在。尽管其对健康的长期影响尚无定论，但这一发现足以令人警醒。减少一次性塑料的使用，或许是每个人力所能及的第一步。",
  "answer": "Các sản phẩm nhựa mang lại tiện lợi cho đời sống con người, đồng thời cũng để lại mối nguy khó phân hủy. Các nhà nghiên cứu đã phát hiện sự tồn tại của vi nhựa ở biển sâu, vùng cực, thậm chí cả trong máu người. Dù ảnh hưởng lâu dài của nó đối với sức khỏe vẫn chưa có kết luận, nhưng phát hiện này đủ để khiến người ta phải cảnh giác. Giảm sử dụng đồ nhựa dùng một lần có lẽ là bước đầu tiên mà ai cũng có thể làm được.",
  "pinyin": "Sùliào zhìpǐn zài gěi rénlèi shēnghuó dài lái biànlì de tóngshí, yě liúxià le nányǐ jiàngjiě de yǐnhuàn. Yánjiū rényuán zài shēnhǎi, jídì nǎizhì réntǐ xuèyè zhōng dōu jiǎncè dào le wēi sùliào de cúnzài. Jǐnguǎn qí duì jiànkāng de chángqī yǐngxiǎng shàng wú dìnglùn, dàn zhè yī fāxiàn zúyǐ lìng rén jǐngxǐng. Jiǎnshǎo yícìxìng sùliào de shǐyòng, huòxǔ shì měi gè rén lìsuǒnéngjí de dì-yī bù.",
