  "hsk30_note": "Kho từ HSK 3.0 gộp cấp 7–9; chưa tách 7/8/9.",
  "hsk20_level": null,
  "title": "AI và việc làm",
  "context": "Hai khách mời tranh luận trong một chương trình về công nghệ.",
  "roles": {
   "A": "Khách mời A",
   "B": "Khách mời B"
  },
  "prompt": "A: Có báo cáo dự đoán rằng trong mười năm tới, trí tuệ nhân tạo sẽ thay thế một lượng lớn công việc mang tính lặp lại.\nB: Lịch sử cho thấy, mỗi cuộc cách mạng công nghệ đều xóa bỏ một số nghề, đồng thời cũng tạo ra những nghề mới.\nA: Nhưng lần này tốc độ thay đổi quá nhanh, người lao động có kịp chuyển đổi không?\nB: Đó chính là điều đáng lo. Chính phủ và doanh nghiệp cần đầu tư nhiều hơn vào đào tạo lại nghề, giúp người lao động chuyển tiếp suôn sẻ.\nA: Vậy với mỗi cá nhân, cách ứng phó tốt nhất là gì?\nB: Bồi dưỡng những năng lực mà máy móc khó sao chép, như tư duy phản biện, sáng tạo và khả năng thấu cảm.",
  "answer": "A：有报告预测，未来十年人工智能将取代大量重复性的工作。\nB：历史表明，每一次技术革命都会淘汰一些职业，同时也会创造新的职业。\nA：可是这一次变化的速度太快了，劳动者来得及转型吗？\nB：这正是值得担忧的地方。政府和企业需要增加对职业再培训的投入，帮助劳动者顺利过渡。\nA：那对个人来说，最好的应对办法是什么？\nB：培养机器难以复制的能力，比如批判性思维、创造力和共情能力。",
  "pinyin": "A: Yǒu bàogào yùcè, wèilái shí nián réngōng zhìnéng jiāng qǔdài dàliàng chóngfùxìng de gōngzuò.\nB: Lìshǐ biǎomíng, měi yí cì jìshù gémìng dōu huì táotài yìxiē zhíyè, tóngshí yě huì chuàngzào xīn de zhíyè.\nA: Kěshì zhè yí cì biànhuà de sùdù tài kuài le, láodòngzhě láidejí zhuǎnxíng ma?\nB: Zhè zhèng shì zhídé dānyōu de dìfang. Zhèngfǔ hé qǐyè xūyào zēngjiā duì zhíyè zài péixùn de tóurù, bāngzhù láodòngzhě shùnlì guòdù.\nA: Nà duì gèrén lái shuō, zuì hǎo de yìngduì bànfǎ shì shénme?\nB: Péiyǎng jīqì nányǐ fùzhì de nénglì, bǐrú pīpànxìng sīwéi, chuàngzàolì hé gòngqíng nénglì.",
