  "hsk20_level": null,
  "title": "Già hóa dân số",
  "prompt": "随着出生率持续走低与平均寿命不断延长，人口老龄化已成为许多国家共同面临的课题。一方面，劳动力短缺可能拖累经济增长；另一方面，养老金和医疗支出的压力与日俱增。对此，有的国家选择推迟退休年龄，有的则大力发展“银发经济”。如何让老年人老有所养、老有所为，考验着社会治理的智慧。",
  "answer": "Cùng với tỷ lệ sinh liên tục giảm và tuổi thọ bình quân không ngừng kéo dài, già hóa dân số đã trở thành vấn đề chung mà nhiều quốc gia phải đối mặt. Một mặt, thiếu hụt lao động có thể kéo lùi tăng trưởng kinh tế; mặt khác, áp lực chi trả lương hưu và chi phí y tế ngày một tăng. Trước tình hình đó, có nước chọn lùi tuổi nghỉ hưu, có nước lại mạnh tay phát triển “kinh tế bạc”. Làm thế nào để người cao tuổi khi về già được chăm lo và vẫn phát huy được vai trò là phép thử đối với trí tuệ quản trị xã hội.",
  "pinyin": "Suízhe chūshēnglǜ chíxù zǒudī yǔ píngjūn shòumìng búduàn yáncháng, rénkǒu lǎolínghuà yǐ chéngwéi xǔduō guójiā gòngtóng miànlín de kètí. Yì fāngmiàn, láodònglì duǎnquē kěnéng tuōlěi jīngjì zēngzhǎng; lìng yì fāngmiàn, yǎnglǎojīn hé yīliáo zhīchū de yālì yǔrì-jùzēng. Duì cǐ, yǒu de guójiā xuǎnzé tuīchí tuìxiū niánlíng, yǒu de zé dàlì fāzhǎn “yínfà jīngjì”. Rúhé ràng lǎoniánrén lǎo yǒu suǒ yǎng, lǎo yǒu suǒ wéi, kǎoyàn zhe shèhuì zhìlǐ de zhìhuì.",
