  "hsk20_level": null,
  "title": "Du lịch “check-in”",
  "prompt": "社交媒体的兴起催生了“打卡式旅游”：游客涌向网上走红的景点，拍完照便匆匆离开。这种走马观花的方式虽然满足了分享的欲望，却难以带来真正的旅行体验。与此同时，短时间内迅速增加的客流也让不少景区的管理捉襟见肘。或许，放慢脚步，用心感受一个地方的历史与人情，才是旅行的意义所在。",
  "answer": "Sự trỗi dậy của mạng xã hội đã sinh ra kiểu “du lịch check-in”: du khách đổ xô đến những điểm đang nổi trên mạng, chụp ảnh xong là vội vã rời đi. Cách “cưỡi ngựa xem hoa” này tuy thỏa mãn mong muốn chia sẻ, nhưng khó mang lại trải nghiệm du lịch thực sự. Đồng thời, lượng khách tăng vọt trong thời gian ngắn cũng khiến công tác quản lý của nhiều khu du lịch rơi vào cảnh xoay xở không kịp. Có lẽ, chậm lại, dụng tâm cảm nhận lịch sử và con người của một vùng đất mới là ý nghĩa thực sự của du lịch.",
  "pinyin": "Shèjiāo méitǐ de xīngqǐ cuīshēng le “dǎkǎ shì lǚyóu”: yóukè yǒng xiàng wǎngshàng zǒuhóng de jǐngdiǎn, pāi wán zhào biàn cōngcōng líkāi. Zhè zhǒng zǒumǎ-guānhuā de fāngshì suīrán mǎnzú le fēnxiǎng de yùwàng, què nányǐ dài lái zhēnzhèng de lǚxíng tǐyàn. Yǔ cǐ tóngshí, duǎn shíjiān nèi xùnsù zēngjiā de kèliú yě ràng bù shǎo jǐngqū de guǎnlǐ zhuōjīn-jiànzhǒu. Huòxǔ, fàngmàn jiǎobù, yòngxīn gǎnshòu yí gè dìfang de lìshǐ yǔ rénqíng, cái shì lǚxíng de yìyì suǒzài.",
