  "prompt": "Nhiều dự án dùng airdrop để thu hút người dùng mới. Người dùng thường phải hoàn thành một số nhiệm vụ, chẳng hạn dùng thử sản phẩm hoặc mời bạn bè. Tuy nhiên, cũng có kẻ lừa đảo lợi dụng airdrop để lừa người dùng kết nối ví. Vì vậy, trước khi tham gia, tốt nhất nên kiểm tra kỹ thông tin trên trang web chính thức của dự án.",
  "answer": "很多项目通过空投来吸引新用户。用户一般需要完成一些任务，比如试用产品或者邀请朋友。不过，也有骗子借空投来骗用户连接钱包。因此，参加之前最好先在项目的官方网站上仔细确认信息。",
  "pinyin": "Hěn duō xiàngmù tōngguò kōngtóu lái xīyǐn xīn yònghù. Yònghù yìbān xūyào wánchéng yìxiē rènwu, bǐrú shìyòng chǎnpǐn huòzhě yāoqǐng péngyou. Búguò, yě yǒu piànzi jiè kōngtóu lái piàn yònghù liánjiē qiánbāo. Yīncǐ, cānjiā zhīqián zuìhǎo xiān zài xiàngmù de guānfāng wǎngzhàn shang zǐxì quèrèn xìnxī.",
