  "hsk30_note": "Kho từ HSK 3.0 gộp cấp 7–9; chưa tách 7/8/9.",
  "hsk20_level": null,
  "title": "Phi tập trung và cái giá phải trả",
  "prompt": "去中心化常被视为区块链最核心的价值，但它并非没有代价。为了让所有节点达成共识，网络往往需要牺牲一部分效率。与此同时，用户必须自己保管私钥，一旦丢失，没有任何机构能够帮忙找回。因此，如何在安全、效率与去中心化之间取得平衡，一直是行业争论的焦点。",
  "answer": "Phi tập trung thường được coi là giá trị cốt lõi nhất của blockchain, nhưng nó không phải là không có cái giá phải trả. Để mọi nút trong mạng đạt được đồng thuận, mạng lưới thường phải hy sinh một phần hiệu suất. Đồng thời, người dùng phải tự bảo quản khóa riêng; một khi bị mất, không có tổ chức nào có thể giúp lấy lại. Vì vậy, làm thế nào để cân bằng giữa an toàn, hiệu suất và tính phi tập trung luôn là tâm điểm tranh luận của ngành.",
  "pinyin": "Qù zhōngxīnhuà cháng bèi shìwéi qūkuàiliàn zuì héxīn de jiàzhí, dàn tā bìngfēi méiyǒu dàijià. Wèile ràng suǒyǒu jiédiǎn dáchéng gòngshí, wǎngluò wǎngwǎng xūyào xīshēng yí bùfen xiàolǜ. Yǔ cǐ tóngshí, yònghù bìxū zìjǐ bǎoguǎn sīyào, yídàn diūshī, méiyǒu rènhé jīgòu nénggòu bāngmáng zhǎo huí. Yīncǐ, rúhé zài ānquán, xiàolǜ yǔ qù zhōngxīnhuà zhījiān qǔdé pínghéng, yìzhí shì hángyè zhēnglùn de jiāodiǎn.",
