  "prompt": "A: Theo bạn, khi thị trường giảm mạnh, người quản lý cộng đồng nên làm gì đầu tiên?\nB: Trước hết phải kịp thời xuất hiện, không thể để cộng đồng nghĩ rằng đội dự án đã \"ôm tiền bỏ chạy\".\nA: Nhưng nếu đội ngũ vẫn chưa có thông tin chính xác thì sao?\nB: Khi đó tôi sẽ thẳng thắn nói rõ điều gì đã được xác nhận, điều gì chưa chắc chắn, đồng thời hẹn thời điểm cập nhật cụ thể.\nA: Còn những tin đồn về giá thì sao?\nB: Tôi tuyệt đối không bình luận về giá, càng không hứa hẹn lợi nhuận; đó là giới hạn không được vượt qua về tuân thủ.",
  "answer": "A：你认为，当市场大幅下跌时，社区经理首先应该做什么？\nB：首先要及时出面，不能让社区觉得项目方已经\"跑路\"了。\nA：可是，如果团队还没有确切的消息呢？\nB：那我会坦诚地说明哪些情况已经确认、哪些还不确定，同时约定具体的更新时间。\nA：那关于价格的传言呢？\nB：我绝不评论价格，更不会承诺收益，这是合规的底线。",
